  /** Advertise custom routes mounted by build(), not routes added afterward. */
  private serviceInfoEndpoints(): Record<string, string> {
    const endpoints: Record<string, string> = {
      rpc: '/api/rpc/*',
      openapi: '/api/*',
      spec: '/api/openapi.json',
      docs: '/api/docs',
      playground: '/api/docs',
      health: '/health',
    };

