    const policyResolver = this.bindContractPolicy();
    const authn = this.authnOptions
      ? createAuthnMiddleware({ ...this.authnOptions, policyResolver })
      : undefined;
    const authz = this.authzOptions
      ? createAuthzMiddleware({
        ...this.authzOptions,
        protect: this.authnOptions?.protect,
        allowAnonymous: this.authnOptions?.allowAnonymous,
        policyResolver,
      })
      : undefined;
    if (authn) this.app.use('*', authn);
    if (authz) this.app.use('*', authz);
    this.authInstalled = true;
  }

  private installBodyLimit(): void {
    if (this.bodyLimitInstalled) return;
    this.bodyLimitInstalled = true;
    if (this.bodyLimitMiddleware) {
      this.app.use('*', this.bodyLimitMiddleware);
    }
  }

  private bindContractPolicy(): ProcedurePolicyResolver | undefined {
    const authorizer = this.authzOptions?.authorizer;
    if (!authorizer || !isContractPolicyAuthorizer(authorizer)) return undefined;

    return authorizer.bind({
      ...resolveRpcWiringPaths(this.rpcOptions ?? undefined),
      rpcAliases: this.rpcOptions?.rpcAliases,
      deprecatedRpcRoutes: this.rpcOptions?.deprecatedRpcRoutes,
    });
  }

  private installDeferredRoutes(): void {
    if (this.deferredRoutesInstalled) return;
    this.deferredRoutesInstalled = true;

    if (this.openApiConfigured) {
      this.app.get(
        '/api/openapi.json',
        createOpenAPISpec(this.router, {
          title: this.openApiOptions?.title ?? `${this.config.name} API`,
          version: this.config.version ?? '1.0.0',
          description: this.openApiOptions?.description,
        }),
      );
    }

    if (this.docsConfigured) {
      this.app.get('/api/docs/scalar.js', createScalarJs());
      this.app.get(
        '/api/docs',
        createScalarDocs({
          specUrl: this.docsOptions?.specUrl ?? '/api/openapi.json',
          title: `${this.config.name} API`,
        }),
      );
    }

    if (this.rpcConfigured) {
      const traceContext = this.rpcOptions?.traceContext !== false;
      wireRpc(
        this.app,
        this.router,
        this.config.name,
        (c) => this.buildRpcContext(c, traceContext),
        this.rpcOptions ?? undefined,
      );
    }

    const routes = [...this.deferredRoutes];
    for (const route of routes) {
      if (route.method === 'all') {
        this.app.all(route.path, route.handler);
      } else {
        this.app[route.method](route.path, route.handler);
      }
    }
    this.installedRoutes = routes;
  }

  /**
   * Builds the app and starts the server.
   *
   * @param options - Server options
   */
  async serve(options?: ServeOptions): Promise<RunningService> {
    await ensureLogging();

    // Run startup hooks before binding the listener.
    for (const hook of this.startupHooks) {
      await hook();
    }

    const app = this.build();
    return startServiceListener(
      app,
      this.config.name,
      this.config.port ?? 3000,
      options,
      this.shutdownHooks,
    );
  }
}

function isContractPolicyAuthorizer(
  authorizer: AuthorizerPort,
): authorizer is ContractPolicyAuthorizerPort {
  return 'bind' in authorizer && typeof authorizer.bind === 'function';
}

