 * app.use('/api/*', async (c, next) => {
 *   const { matched, response } = await openApiHandler.handle(c.req.raw, {
 *     prefix: '/api',
 *     context: {},
 *   });
 *   if (matched) return c.newResponse(response.body, response);
 *   return await next();
 * });
 * ```
 */
